-- file: functions/_private/game_was_pickable.sql
-- _game_was_pickable: could this league have picked this game before it kicked off?
--
-- The pickability half of the settlement gate (ADR-0040, #803), and the structural mirror of
-- _participation_start: that helper bounds the missed-penalty population in TIME, this one
-- bounds it by whether picking was ever POSSIBLE at all.
--
-- lock_pick / lock_pick_all_groups refuse a pick on a game with no active line for the
-- league's source ('no active line for game % (source=%)'). The missed-penalty pass in
-- _grade_games_by_ids had no matching gate -- its comment said outright that "line is
-- irrelevant for missed picks" -- so a game that reached kickoff unlined charged every
-- active member the -1 for an inaction the system had structurally forbidden them to avoid.
--
-- "Pickable" here means: a game_lines row existed for this league's line_source at or before
-- kickoff. Three deliberate choices inside that predicate:
--
--   * The source is resolved from group_config exactly the way lock_pick_all_groups resolves
--     it (coalesce(line_source, 'fanduel')), so the pick path and the grade path can never
--     disagree about which book a league plays off. A line filed under a DIFFERENT source
--     cannot make a game gradable-but-unpickable.
--   * fetched_at <= commence_time, NOT is_active_line. is_active_line is a live pointer that
--     a post-kickoff sync can move (and its unique index is per game, not per source), while
--     this asks the historical question the penalty turns on: was there ever a line to pick?
--     It is deliberately the same population _capture_closing_line flags, so "was pickable"
--     and "has a closing line" describe the same set once capture has run -- but unlike
--     is_closing_line it is also correct BEFORE the game's first grade, which is what
--     _settlement_owed needs (capture only ever runs on the grade path, #735).
--   * Existence, not currency. game_lines is append-only, so a row fetched pre-kickoff is
--     durable proof the game was pickable at some point before it started.
--
-- SECURITY DEFINER for the same reason as _participation_start and _settlement_owed: the
-- answer is a scoring fact, and a caller reading under RLS must not see a different verdict
-- than grading used. Born closed to anon/authenticated by the _close_new_fn_acl event trigger
-- (schemas/0000_function_acl_guard.sql, ADR-0011); an internal helper, never a client RPC.
create or replace function public._game_was_pickable(p_group_id uuid, p_game_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.games g
    join public.game_lines gl
      on gl.game_id = g.id
     and gl.fetched_at <= g.commence_time
     and gl.source = coalesce(
           (select gc.line_source from public.group_config gc where gc.group_id = p_group_id),
           'fanduel'
         )
    where g.id = p_game_id
  );
$$;

comment on function public._game_was_pickable(uuid, uuid) is
  'ADR-0040 / #803: true when a game_lines row for this league''s line_source existed at or before kickoff -- i.e. when lock_pick would have accepted a pick. The missed-penalty pass in _grade_games_by_ids and _settlement_owed both gate on it, so a game nobody was permitted to pick charges nobody and does not strand the reconcile sweep.';

-- file: functions/_private/grade_games_by_ids.sql
-- This is a new internal helper function. Note the leading underscore.
create or replace function public._grade_games_by_ids(p_game_ids uuid[])
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_missing_closing text;
begin
  -- Freeze imported seasons (ADR-0024): never (re)grade a game in a locked season.
  -- Strips locked-season games up front so closing-line capture and BOTH settlement
  -- passes below operate only on gradable games. This is the single choke point --
  -- grade_game / grade_week / grade_season and the grade cron all funnel through here,
  -- as will the #433 reconcile sweep -- so a locked (pre-2025 imported) season is inert
  -- to every grade path and its sheet-sourced settlements can never be re-derived.
  select coalesce(array_agg(g.id), '{}')
    into p_game_ids
  from public.games g
  join public.weeks w on w.id = g.week_id
  join public.seasons s on s.id = w.season_id
  where g.id = any(p_game_ids)
    and not s.grading_locked;

  if array_length(p_game_ids, 1) is null then
    return;
  end if;

  -- Capture the closing line for each game before grading (write-once).
  perform public._capture_closing_line(p_game_ids);

  -- Under House the closing line IS the graded line (ADR-0007), so refuse to grade a
  -- House row without one instead of silently substituting the pick-time line (#735).
  -- Runs AFTER capture above, so it can only fire when no pre-kickoff game_lines row
  -- ever existed to flag -- broken data, not a capture-timing artifact. It is the
  -- reason the House branch below reads cl.spread_* directly: grade_pick's margin
  -- comparisons are all false against a NULL spread, so it would fall through to
  -- 'loss' for EVERY pick on the game rather than failing. This predicate is the exact
  -- negation of that branch's `cl` lateral -- same effective-preset chain, same
  -- line_source, evaluated per pick row -- so the two can never disagree. Games with no
  -- picks are excluded: the missed-penalty pass below never reads a line.
  select string_agg(distinct m.game_id::text, ', ')
    into v_missing_closing
  from (
    select g.id as game_id
    from public.games g
    join public.picks p on p.game_id = g.id
    left join public.group_config cfg on cfg.group_id = p.group_id
    left join public.pick_settlement ps_prior
      on ps_prior.group_id = p.group_id
     and ps_prior.user_id  = p.user_id
     and ps_prior.game_id  = g.id
    left join lateral (
      select ps2.graded_preset
      from public.pick_settlement ps2
      where ps2.group_id = p.group_id
        and ps2.game_id  = g.id
      limit 1
    ) ps_cohort on true
    where g.id = any(p_game_ids)
      and coalesce(ps_prior.graded_preset, ps_cohort.graded_preset, cfg.grading_preset, 'gamer') = 'house'
      and not exists (
        select 1
        from public.game_lines gl
        where gl.game_id = g.id
          and gl.source  = coalesce(cfg.line_source, 'fanduel')
          and gl.is_closing_line
      )
  ) m;

  if v_missing_closing is not null then
    raise exception
      'grade: House preset requires a closing line but none exists for game(s) %; refusing to grade on the pick-time line (ADR-0007, #735)',
      v_missing_closing
      using errcode = 'P0001';
  end if;

  -- (1) Upsert settlements for users who DID make a pick on the given games.
  -- Effective preset = coalesce(this row's own prior, any cohort row already graded for
  -- this game, group config, 'gamer'). Frozen per game, first grade wins (ADR-0007
  -- 2026-07-15 amendment, #657): ps_prior alone only freezes a row that already exists,
  -- so a row born late into an already-graded game (added member, backfilled gap) fell
  -- through to today's group config instead of its game's frozen preset. ps_cohort closes
  -- that gap by checking ANY settlement already graded for this (group, game), not just
  -- this user's own.
  insert into public.pick_settlement (group_id, user_id, game_id, pick_id, points_delta, outcome, graded_at, graded_preset)
  select
    p.group_id,
    p.user_id,
    g.id,
    p.id,
    gp.points_delta,
    gp.outcome,
    now(),
    eff.preset
  from public.games g
  join public.picks p on p.game_id = g.id
  left join public.group_config cfg on cfg.group_id = p.group_id
  left join public.pick_settlement ps_prior
    on ps_prior.group_id = p.group_id
   and ps_prior.user_id  = p.user_id
   and ps_prior.game_id  = g.id
  left join lateral (
    select ps2.graded_preset
    from public.pick_settlement ps2
    where ps2.group_id = p.group_id
      and ps2.game_id  = g.id
    limit 1
  ) ps_cohort on true
  left join lateral (
    select gl.spread_team_id, gl.spread_value
    from public.game_lines gl
    where gl.game_id = g.id
      and gl.source  = coalesce(cfg.line_source, 'fanduel')
      and gl.is_closing_line
    limit 1
  ) cl on true
  cross join lateral (
    select coalesce(ps_prior.graded_preset, ps_cohort.graded_preset, cfg.grading_preset, 'gamer') as preset
  ) eff
  cross join lateral public.grade_pick(
    (g.final_scores->>'home')::int,
    (g.final_scores->>'away')::int,
    g.home_team_id,
    g.away_team_id,
    p.picked_team_id,
    -- House reads the closing line directly -- no coalesce to the pick-time line. The
    -- guard above has already proven cl is present for every House row here, and a
    -- fallback would be exactly the silent degradation #735 was filed for.
    case when eff.preset = 'house'
         then cl.spread_team_id
         else p.locked_spread_team_id end,
    case when eff.preset = 'house'
         then cl.spread_value
         else p.locked_spread_value end,
    p.weight::text
  ) as gp
  where g.id = any(p_game_ids)
  on conflict (group_id, user_id, game_id)
  do update set
    pick_id      = excluded.pick_id,
    points_delta = excluded.points_delta,
    outcome      = excluded.outcome,
    graded_at    = excluded.graded_at,
    graded_preset = excluded.graded_preset;

  -- (2) Upsert "missed" penalties for every ACTIVE league member who did NOT make a pick.
  -- Population is group membership, NOT global users.role (ADR-0024): the missed penalty is
  -- a league-participation rule, so a competing app-admin (users.role='admin') is penalized
  -- exactly like any other member -- the prior u.role='player' filter silently exempted the
  -- admin, which flipped the 2022 champion after the #430 re-grade. 'pending' invites are
  -- excluded. Admin app-access (is_admin(), settings/audit_log RLS) is unaffected by this.
  -- graded_preset is set for consistency; the penalty AMOUNT still never reads a line (House
  -- vs Gamer cannot change what a non-pick is worth).
  --
  -- The population is bounded in PICKABILITY by _game_was_pickable (ADR-0040, #803): a member
  -- is penalized only for a game their league could actually have picked -- one with a
  -- game_lines row for the league's line_source at or before kickoff. lock_pick refuses a
  -- pick on a game with no active line, so without this gate an unlined game charged every
  -- active member -1 for an inaction the system itself had forced. It bites hardest exactly
  -- when something upstream has already broken: an Odds API quota freeze can leave a whole
  -- slate unlined, costing every player -1 x the full slate. The gate is per-LEAGUE, not
  -- per-game -- line_source is group_config, so a league playing off a book that never posted
  -- this game is exempt while a league on the book that did still pays.
  --
  -- Deliberately gated on the POPULATION rather than inside resolve_missed_penalty_for_game():
  -- zeroing the penalty would still write a 'missed' row, which reads as a skipped pick to
  -- every downstream surface (streaks, ratings, the who's-picked board). The correct answer
  -- for a game nobody was permitted to pick is no row at all. The completeness pair reads the
  -- same rule through _settlement_owed, so a now-rowless game is not flagged unsettled forever.
  --
  -- The population is additionally bounded in TIME by the participation boundary (ADR-0037,
  -- #712): a member is penalized only for a game that started on or after
  -- _participation_start(group, member) = greatest(league competition start, their join).
  -- Without it this pass manufactured a miss for every game played before a member joined --
  -- or before the league existed -- on EVERY re-grade, and grade_season reaches the whole
  -- unlocked season. Pass (1) above needs no such gate: a pre-participation game cannot have
  -- a pick to grade.
  --
  -- This gates what gets WRITTEN; it is not a delete. An already-settled row outside the
  -- boundary is left alone by design -- post-fix the only way that arises is remove-then-
  -- rejoin (a fresh membership row with a later joined_at), where ADR-0037 ruling 6
  -- deliberately preserves the member's pre-removal graded history.
  insert into public.pick_settlement (group_id, user_id, game_id, pick_id, points_delta, outcome, graded_at, graded_preset)
  select
    gm.group_id,
    u.id,
    g.id,
    null,
    public.resolve_missed_penalty_for_game(g.id),
    'missed'::public.pick_outcome,
    now(),
    coalesce(ps_prior.graded_preset, ps_cohort.graded_preset, cfg.grading_preset, 'gamer')
  from public.games g
  cross join public.group_memberships gm
  join public.users u on u.id = gm.user_id
  left join public.group_config cfg on cfg.group_id = gm.group_id
  left join public.pick_settlement ps_prior
    on ps_prior.group_id = gm.group_id
   and ps_prior.user_id  = u.id
   and ps_prior.game_id  = g.id
  left join lateral (
    select ps2.graded_preset
    from public.pick_settlement ps2
    where ps2.group_id = gm.group_id
      and ps2.game_id  = g.id
    limit 1
  ) ps_cohort on true
  where g.id = any(p_game_ids)
    and gm.status = 'active'
    and g.commence_time >= public._participation_start(gm.group_id, u.id)
    and public._game_was_pickable(gm.group_id, g.id)
    and not exists (
      select 1
      from public.picks p
      where p.group_id = gm.group_id
        and p.game_id = g.id
        and p.user_id = u.id
    )
  on conflict (group_id, user_id, game_id)
  do update set
    -- Only update if the existing settlement is also for a missed pick.
    -- This prevents overwriting a real pick that was graded out of order.
    pick_id       = excluded.pick_id,
    points_delta  = excluded.points_delta,
    outcome       = excluded.outcome,
    graded_at     = excluded.graded_at,
    graded_preset = excluded.graded_preset
  where pick_settlement.pick_id is null;
end;
$$;

-- file: functions/_private/settlement_owed.sql
-- _settlement_owed: does grading owe ANY pick_settlement row for this game?
--
-- The negative space of the participation boundary (ADR-0037, #724). The completeness
-- surfaces -- find_unsettled_weeks() (#433) and advance_week_if_complete() (#658) -- both
-- define "unsettled" as "this game is final but has ZERO pick_settlement rows". That
-- predicate silently assumed grading always owes at least one row per game, which was true
-- before ADR-0037 bounded the missed-pass in time: every active member of every league was
-- penalizable for every game, so any final game acquired rows.
--
-- With the boundary in force a game can legitimately owe NOTHING: a league created in week
-- 10, or a league whose only members joined later, has no eligible (member, game) pair for
-- the earlier weeks. _grade_games_by_ids correctly writes no row for such a game -- so the
-- zero-row test flags it forever. The reconcile sweep would re-fire on every tick against a
-- week it can never heal, and advance_week_if_complete would never report that week complete
-- (which in turn keeps the grade cron's #744 settled-prior-week gate from ever releasing it).
--
-- So both callers gain this predicate: a final game is only "unsettled" if a row is actually
-- owed. Owed means either
--   (a) some ACTIVE membership anywhere is eligible for it -- the missed-pass population,
--       gated by the same public._participation_start AND public._game_was_pickable that the
--       grading choke point uses; or
--   (b) a real pick exists on it -- pass (1) of _grade_games_by_ids grades real picks with
--       no boundary gate (ADR-0037 ruling 2), so a pick from a since-removed member still
--       produces a row and must still be swept for.
--
-- Pickability joined clause (a) for exactly the reason the boundary did (ADR-0040, #803).
-- Once the missed pass stopped charging for a game no league was permitted to pick, an
-- unlined game with no picks became a SECOND way to legitimately owe nothing -- and the
-- zero-row test would have flagged it forever, re-firing the reconcile sweep on every tick
-- and keeping its week from ever reporting complete. Every gate the write side gains, this
-- predicate must gain too, or the two disagree about what is still outstanding.
--
-- _game_was_pickable reads game_lines.fetched_at rather than is_closing_line specifically so
-- it works here: this function runs on games that have NOT been graded yet, and the closing
-- flag is only ever set by _capture_closing_line on the grade path (#735). Keying off the
-- flag would report "not owed" for every ungraded game and the sweep would heal nothing.
--
-- Deliberately group-agnostic in its SIGNATURE: both callers are global (cross-league) and
-- only ask whether the GAME is stranded, not which league stranded it. Both gates are still
-- evaluated per-membership inside, since participation start and line_source are per-league.
--
-- SECURITY DEFINER for the same reason as _participation_start: the answer is a grading fact
-- and must not vary with the caller's RLS view of group_memberships/picks. Born closed to
-- anon/authenticated by the _close_new_fn_acl event trigger (ADR-0011); internal helper,
-- never a client RPC.
create or replace function public._settlement_owed(p_game_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select
    exists (
      select 1
      from public.games g
      cross join public.group_memberships gm
      where g.id = p_game_id
        and gm.status = 'active'
        and g.commence_time >= public._participation_start(gm.group_id, gm.user_id)
        and public._game_was_pickable(gm.group_id, g.id)
    )
    or exists (
      select 1
      from public.picks p
      where p.game_id = p_game_id
    );
$$;

comment on function public._settlement_owed(uuid) is
  'ADR-0037 / #724 + ADR-0040 / #803: true when grading owes at least one pick_settlement row for this game -- some active membership is both eligible under _participation_start and able to pick it under _game_was_pickable, or a real pick exists. The completeness surfaces (find_unsettled_weeks, advance_week_if_complete) use it so a game no league was participating in, or that no league could pick, is not flagged as permanently unsettled.';
